namespace ghidra.app.plugin.core.debug.gui.model.columns;

using docking.widgets.table;
using ghidra.app.plugin.core.debug.gui.model.PathTableModel;
using ghidra.docking.settings;
using ghidra.framework.plugintool;
using ghidra.trace.model;
using ghidra.trace.model.target;
using ghidra.trace.model.target;
using ghidra.util.table.column;

public class TracePathLastKeyColumn : AbstractDynamicTableColumn<PathRow, string, Trace> {
	private TracePathColumnRenderer<string> renderer = new();

	/* @Override */
	public string getColumnName() {
		return "Key";
	}

	/* @Override */
	public GColumnRenderer<string> getColumnRenderer() {
		return renderer;
	}

	/* @Override */
	public string getValue(PathRow rowObject, Settings settings, Trace data,
			ServiceProvider serviceProvider)
    {
		TraceObjectValPath path = rowObject.getPath();
		TraceObjectValue lastEntry = path.getLastEntry();
		if (lastEntry == null) {
			return "<root>";
		}
		return lastEntry.getEntryKey();
	}
}
